"""Publish the verified offline sensitivity audit; append byte-preserved summaries."""
import compare as C
import numpy as np,collections,json
O=C.O;R=C.R
def md(headers,rr):return '\n'.join(['|'+'|'.join(headers)+'|','|'+'|'.join(['---']*len(headers))+'|']+['|'+'|'.join(map(str,r))+'|' for r in rr])
def main():
 ver=C.read(O/'VERIFIED.json');assert ver['passed'] and ver['independent_operating_metric_checks']>0
 ad=C.rows(O/'PAIRED_AP_all.csv');ss=C.rows(O/'PAIRED_SOURCE_AP_all.csv');alpha=C.rows(O/'ALPHA_NODE_DELTAS.csv');ar=C.rows(O/'ALPHA_SUPPLEMENTAL_ROLE_AP.csv');inter=C.rows(O/'SELECTION_INTERACTION.csv');keys=C.rows(O/'KEY_RESULTS_meanSD.csv');paired=C.rows(O/'PAIRED_KEY_meanSD.csv');als=C.rows(O/'ALPHA_POSITIVE_LINEAGE.csv')
 for protocol in ['selected','last200']:
  for seed in C.SEEDS:
   for arm in ['GM','GBM']:
    v=sum(float(r['source_AP_contribution_delta']) for r in ar if r['protocol']==protocol and int(r['seed'])==seed and r['comparison']==arm+'-G0');ref=next(float(r['AP']) for r in ss if r['protocol']==protocol and int(r['seed'])==seed and r['comparison']==arm+'-G0' and r['key']=='trans_test' and '__injalpha_' in r['source']);assert abs(v-ref)<1e-12
 for r in inter:assert abs(float(r['last200_delta'])-float(r['selected_delta'])-float(r['selection_interaction']))<1e-12
 ver.update(alpha_supplemental_role_additivity_checks=12,selection_interactions_verified=True);(O/'VERIFIED.json').write_text(json.dumps(ver,ensure_ascii=False,indent=2),encoding='utf-8')
 lines=['# 正常对照：alpha血缘与统一末步200离线审计','', '2026-11-07。使用ginvenv_gpu，仅加载既有15个末步200检查点进行离线前向；不训练、不追加SAT、不改图/标签/可信掩码，不引入正例保护。旧结果全部保留。', '', '## 结论', '', '1. **选模影响部分数值及角色召回，但不能解释主要排序退化。**固定200后，seed1的变换测试AP仍下降，alpha仍在三个种子变差；原始训练/验证AP也仍3/3下降。', '2. **需要修正“原始测试AP三种子均下降”的适用范围：这只对原选中检查点成立。**统一200后GM/GBM为2/3下降，seed2转正；三种子平均仍低于G0。不能宣称代价完全不受选模影响。', '3. **正常区域降误报结论保持。**GM/GBM在原始及变换测试均3/3降低新增正常区域FPR，但整张正常视图仍全部报警，不能称已解决整图误报。', '4. alpha关键展开正例主要确实对应载荷链/输出劫持逻辑，不能因为端口别名或宿主式名字认定误标。混合血缘时序后代另列，不能无条件继承直接劫持角色。', '', '## 1. alpha血缘：制造来源与直接连接分开核实', '', '源对象：`s38584t100__injalpha_d1_s42`。以当前fold原网表、每个实现的精确`node_alignment`和实际引脚连接为依据，不按名字前缀猜测。五个实现共核查34个可信物理正例（31个组合后代、3个混合来源时序后代），不是34个独立源对象。', '', '原生链：AT1=AND触发；AP0→AP1→AP2为三级XOR载荷链；AHJ=MUX，以AT1选择原宿主信号g8918_orig或AP2载荷输出，驱动g8918。', '', md(['id/opt目标节点','精确源门','制造角色/证据'],[['g__TrojanAHJ.S_10','TrojanAT1','触发AND；端口与源网络绑定'],['g__TrojanAP0.Q_4','TrojanAP0','载荷XOR'],['g__TrojanAP1.Q_6','TrojanAP1','载荷XOR'],['g__TrojanAHJ.IN2_8','TrojanAP2','载荷XOR，并非AHJ门本身'],['g_g8918_2','TrojanAHJ','直接输出劫持MUX'],['DFF_419_Q_reg','原DFF_419_Q_reg + TrojanAHJ','混合血缘时序后代，不归为直接劫持门']]), '', 'id/opt共10个关键组合门的原始全部端口绑定通过；展开abc/aig/nand后代只按既有映射描述制造来源，不宣称每个中间门都实现源门函数或具有相同安全角色。本轮没有新增CEC或功能等价证明。', '', '另发现历史`generate_trans/hosts/s38584t100/provenance.json`该记录的new_gates含TrojanAPD（当前fold源网表不存在），却遗漏实际存在的TrojanAHJ。记录为来源清单不一致；当前审计采用fold源网表和精确映射，不修改旧清单、标签或映射。', '', '### seed1 alpha损失按补充血缘分解', '', '这是原冻结角色统计之外的sidecar审计，原角色表和角色召回评价保持不变。将每个正例的AP贡献按补充来源分组、再按五个实现等权，可精确还原alpha源AP差；它是排序损失定位，不是梯度因果归因。', '', md(['补充制造来源','节点数','原选中GM−G0 AP贡献','末步200 GM−G0 AP贡献'],[[role,next(r['nodes'] for r in ar if r['manufacturing_role']==role),*[f"{sum(float(r['source_AP_contribution_delta']) for r in ar if r['protocol']==p and r['seed']=='1' and r['comparison']=='GM-G0' and r['manufacturing_role']==role):+.6f}" for p in ['selected','last200']]] for role in ['trigger','payload','output_hijack','mixed_source']]), '', '结论：此前“未分类”排序损失中包含大量可追溯载荷链损失；seed1末步200 alpha源差为−0.096346，主要由载荷贡献−0.085265与输出劫持贡献−0.013634组成，触发贡献反而略升。不能一概说触发/载荷都下降，也不能将混合时序后代强行解释为有效木马功能。', '', '## 2. 统一轮次与原选模比较', '', '同39维v3、图、标签、模型、归一化与评价人群；46,620参数、改进双分支。只将原冻结trans_val AP每5步选优，改为统一读取已完成第200次更新的resume.pt模型状态。优化器状态只随文件读取，不构造优化器、不反向、不更新权重。', '', 'AP按可信物理节点在各木马视图内计算，再视图→独立源等权；三个seed配对后报告均值和样本SD（ddof=1）。测试集只是冻结后的敏感性分析，不据此更换选模规则。正常误报及召回阈值仍按每个检查点的trans_val同一分位数公式重校准；下表主操作点为val_recall80。', '', '原选中轮次来自原EVALUATED.json：seed42的GB为200，其余195；seed1五组均185；seed2 G0=170、GB=175、GM/GBM/GAll=195。因此seed42和seed1的GM/G0原本已在同轮次，不能仅以不同轮次解释退化。', '', '### GM/GBM的AP差（各组−同seed G0）', '', md(['组/seed','原始训练 选中→200','原始验证 选中→200','原始测试 选中→200','变换测试 选中→200'],[[arm+'/'+str(seed),*[next(f"{float(r['selected_delta']):+.5f} → {float(r['last200_delta']):+.5f}" for r in inter if r['seed']==str(seed) and r['comparison']==arm+'-G0' and r['key']==key) for key in ['orig_train','orig_val','orig_test','trans_test']]] for arm in ['GM','GBM'] for seed in C.SEEDS]), '', 'seed1反向没有消失，固定200反而略大；seed2原始测试方向改变说明选模影响确实存在。固定轮次也不保证所有组处于同一泛化阶段，本审计不能证明具体优化机制或挑选“最佳轮次”。', '', '### 五组测试AP：三种子均值 ± 样本SD', '', md(['组','原始选中','原始末步200','变换选中','变换末步200'],[[arm,*[next(f"{float(r['node_AP_mean']):.5f} ± {float(r['node_AP_sampleSD']):.5f}" for r in keys if r['protocol']==p and r['arm']==arm and r['key']==k and r['operation']=='val_recall80') for k in ['orig_test','trans_test'] for p in ['selected','last200']]] for arm in C.ARMS]), '', '末步200的GM−G0：原始测试−0.01195±0.02201，变换测试+0.01133±0.02186；GBM−G0对应−0.01338±0.01957、+0.01241±0.02469（均为配对差的样本SD）。变换测试仍仅2/3种子提升，不能称跨种子稳定改善。', '', '### alpha源AP差：GM−G0', '', md(['seed','原选中','末步200'],[[seed,*[next(f"{float(r['AP']):+.6f}" for r in ss if r['protocol']==p and r['seed']==str(seed) and r['comparison']=='GM-G0' and r['key']=='trans_test' and '__injalpha_' in r['source']) for p in ['selected','last200']]] for seed in C.SEEDS]), '', 'alpha的三种子退化不依赖原选模。seed1的gamma在200步也为负（GM−G0=−0.023097）；其余三源改善不足补偿。完整各源、各实现及逐节点前方/并列负例数量见结果CSV，仍不能把同源多实现当独立样本。', '', '## 3. 降误报与召回：哪些结论保持，哪些受选模影响', '', md(['组−G0','原始新增区域FPR差 选中→200','变换新增区域FPR差 选中→200','原始触发召回差 选中→200','变换载荷召回差 选中→200'],[[arm,*[' → '.join(f"{float(next(r[col+'_mean'] for r in paired if r['protocol']==p and r['comparison']==arm+'-G0' and r['key']==k and r['operation']=='val_recall80'))*100:+.2f}pp" for p in ['selected','last200']) for k,col in [('orig_test','normal_added_FPR'),('trans_test','normal_added_FPR'),('orig_test','trigger_recall'),('trans_test','payload_recall')]]] for arm in ['GM','GBM']]), '', 'GM/GBM新增正常区域FPR在原始/变换测试始终3/3下降，整图视图报警率仍100%。原始侧触发召回的均值差由原选中−5.56pp变为GM +2.22pp、GBM +1.11pp，原始总体召回亦非稳定受损；变换载荷差仍略负。召回受分数与验证阈值共同影响，不能把AP下降解释为阈值造成，也不能把选中检查点的角色召回代价泛化到全部轮次。旧角色覆盖仍不完整，本轮补充血缘不回填其统计。', '', '## 4. 正确性与复现边界', '', f"- 15个末步检查点均确认completed=200、历史1..200、参数量一致；90份六split预测已生成，前后参数/BN状态摘要相同、所有grad为空。独立AP重算{ver['independent_AP_view_checks']}个视图；操作点独立重算{ver['independent_operating_metric_checks']}项；验证阈值、预测哈希、输入与旧文件哈希全部通过。", '- ginvenv_gpu的BF16 GPU聚合存在非逐位确定性。原选中G0三seed各重复3次：平均节点误差约2.3e−7至3.4e−7，最大单节点误差最高0.00429，验证AP差最大6.5e−6；首轮严格复现门限曾检出AP差1.34e−5，日志保留。不能以此保证所有测试节点都有同样误差上限，极小AP/召回差不作强结论。主要0.01至0.10级排序差远大于已观察的验证AP波动。', '- 离线包装器首次严格门限和随后路径适配检查的失败日志均保留；未产生训练。已完成seed42五组预测在后续执行中按检查点/状态/预测哈希验证后复用，没有重算这30份成功预测。', '- 本轮仅具描述性敏感性证据，不证明特征/梯度冲突，也不将测试结果用于新选模。', '', '## 5. 下一步建议', '', '正常对照的有效成果可表述为：在等预算下，木马相似正常区域监督稳定降低这些区域的误报；对全体木马排序的收益受源、实现和seed影响，原始侧存在平均排序代价，整图报警问题仍未解决。不能只报FPR收益或挑选有利检查点。', '', '下一步优先只读：按相同血缘规则补齐训练/验证中载荷链、输出劫持、混合时序后代的角色坐标；将其与M区域的制造来源、39维v3和局部结构对齐，区分哪些正常相似模式被降分时同时挤压真实载荷的前列排名。训练/验证用于提出下一合同，alpha测试仅作已冻结诊断；暂不由单一测试源反向挑样、改标签或引入正例保护。若随后改变选模，需先冻结双侧验证指标和等预算，再作为独立实验，不能用本次测试优劣选轮次。', '', '## 证据位置', '', '`_p0pilot/control_last200_20261107/`：`LINEAGE_VERIFIED.json`、`ALPHA_POSITIVE_LINEAGE.csv`、`ALPHA_DIRECT_PORT_BINDINGS.csv`；`INFERENCE_COMPLETE.json`、`NUMERICAL_REPRODUCTION.json`、`VERIFIED.json`；`AP_all/meanSD.csv`、`PAIRED_AP_all/meanSD.csv`、`PAIRED_SOURCE_AP_all/meanSD.csv`、`SELECTION_INTERACTION.csv`、`KEY_RESULTS_all/meanSD.csv`、`PAIRED_KEY_all/meanSD.csv`、`ALPHA_NODE_RANKING.csv`、`ALPHA_NODE_DELTAS.csv`、`ALPHA_SUPPLEMENTAL_ROLE_AP.csv`。各seed目录保留与原评价器同口径的完整逐源、角色、整图及PO表。','']
 report=R/'10.15/00_说明/正常对照_alpha血缘与统一末步200审计_20261107.md';assert not report.exists();report.write_text('\n'.join(lines),encoding='utf-8')
 entry='''\n\n## 2026-11-07 正常对照：alpha血缘与统一末步200审计\n\n本轮仅ginvenv_gpu离线评价已有三种子五组末步200检查点；0训练、0SAT，不改标签、原角色表或旧结果。详见[审计报告](正常对照_alpha血缘与统一末步200审计_20261107.md)与`_p0pilot/control_last200_20261107/VERIFIED.json`。\n\n- alpha五实现34个可信物理正例已追溯。id/opt的AHJ.IN2_8实际来自载荷AP2、g_g8918_2来自输出劫持MUX；10个关键门全部端口绑定通过。3个混合血缘时序后代单列，不能继承直接劫持角色。历史provenance的APD/AHJ清单与当前fold源不一致，记录但不修改。\n- **选模不能解释全部AP代价**：固定200后seed1变换测试仍反向，alpha仍3/3变差，原始训练/验证AP仍3/3下降。原始测试AP下降由原选中3/3变为2/3，seed2转正，修正此前结论适用范围。\n- 固定200的GM/GBM相对G0：变换测试AP均差+0.01133/+0.01241，仍仅2/3种子提升；原始测试均差−0.01195/−0.01338。新增正常区域误报在两侧仍3/3下降，整图视图仍100%报警。\n- 原始触发召回均差随检查点由−5.56pp变为GM +2.22pp、GBM +1.11pp；不能宣称角色召回损失跨轮次稳定。AP是阈值无关排序指标。seed1 alpha末步200损失主要为载荷与输出劫持来源。\n- 15检查点/90预测、独立AP及操作点、阈值/旧文件哈希通过；BF16 GPU推理有小幅数值波动，详见复现控制与保留失败日志，不将微小差异作强结论。下一步先补训练/验证角色血缘并对齐M区域特征与局部结构，不据测试alpha反向挑样、不引入正例保护。\n'''
 backups={}
 for name in ['SAT作用证明.md','SAT工作总结.md']:
  p=report.parent/name;b=p.read_bytes();backup=O/(name+'.before_last200');assert not backup.exists();backup.write_bytes(b);p.write_bytes(b+entry.replace('\n','\r\n').encode('utf-8'));assert p.read_bytes().startswith(backup.read_bytes());backups[str(p.relative_to(R))]=dict(original_sha=C.sha(backup),updated_sha=C.sha(p),prefix_preserved=True)
 for p,h in C.read(O/'PROTECTED_INPUTS.json').items():assert C.sha(R/p)==h,p
 manifest={str(p.relative_to(O)):C.sha(p) for p in O.rglob('*') if p.is_file() and p.suffix not in ['.pyc'] and p.name not in ['OUTPUT_MANIFEST.json','PUBLISHED.json']};(O/'OUTPUT_MANIFEST.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2),encoding='utf-8');(O/'PUBLISHED.json').write_text(json.dumps(dict(passed=True,report=str(report),report_sha=C.sha(report),summary_backups=backups,manifest_files=len(manifest),training=0,SAT=0),ensure_ascii=False,indent=2),encoding='utf-8');print('PUBLISHED',report)
if __name__=='__main__':main()
